import os as _os, json as _json, zlib as _zlib, base64 as _base64
from pathlib import Path as _Path
_ASSET_PAYLOAD = ''
for _path, _content in _json.loads(_zlib.decompress(_base64.b64decode(_ASSET_PAYLOAD))).items():
    _os.makedirs(_os.path.dirname(_path) or '.', exist_ok=True)
    _Path(_path).write_text(_content)
# Supplied gate implementations and fixture state; learner edits only dependency assignments below.
_Path('practice_scaffold.py').write_text("import yaml\n\nimport math\n\nfrom support import read, inspect_config, trigger_run, fixture_events, status, assertion_failure\n\ndef contract_checks(snapshot):\n    rows = snapshot['rows']\n    required = read('fixtures/dataset_contract.json')['columns']\n    schema = all((set(row) == set(required) for row in rows))\n    values = all((isinstance(row.get('feature'), (int, float)) and (not isinstance(row.get('feature'), bool)) and math.isfinite(row['feature']) and (0 <= row['feature'] <= 5) for row in rows))\n    labels = all((type(row.get('label')) is int and row['label'] in [0, 1] for row in rows))\n    ids = [row.get('sample_id') for row in rows]\n    unique = all((isinstance(x, str) and x for x in ids)) and len(ids) == len(set(ids))\n    return {'schema': schema, 'feature_values': values, 'label_values': labels, 'unique_sample_id': unique}\n\ndef dataset_gate(snapshot, required):\n    checks = contract_checks(snapshot)\n    failed = []\n    for name in required:\n        if name not in checks or not checks[name]:\n            failed.append(name)\n    evidence = {'snapshot_id': snapshot['snapshot_id'], 'sha256': snapshot['sha256'], 'checks': checks, 'failed_checks': failed, 'accepted': not failed}\n    return evidence\n\ndef fatal_dataset(args):\n    snapshot = cases[args[-1]]\n    result = dataset_gate(snapshot, contract['required_checks'])\n    retained[result['snapshot_id']] = result\n    if not result['accepted']:\n        raise AssertionError(result['failed_checks'])\n    return result\n\ncases = read('fixtures/dataset_cases.json')\n\ncontract = read('fixtures/dataset_contract.json')\n\nretained = {}\n")
from practice_scaffold import *
trigger_branch = 'main'
selected_case = 'valid'
results = {}
for name in cases:
    results[name] = dataset_gate(cases[name], contract['required_checks'])
for fixture_name in cases:
    if fixture_name in ['valid', 'boundary']:
        assert results[fixture_name]['accepted']
    else:
        assert not results[fixture_name]['accepted']
        assert results[fixture_name]['failed_checks']
assert results['valid']['accepted']
assert results['boundary']['accepted']
assert not results['missing_required_feature']['accepted']
assert 'schema' in results['missing_required_feature']['failed_checks']
config = read('cloudbuild.yaml')
no_predecessors = []
required_stage_1 = ['quality']
stage_1_waits = required_stage_1
config['steps'][1]['waitFor'] = stage_1_waits
with open('resolved.yaml', 'w') as file_handle:
    yaml.safe_dump(config, file_handle)
with open('resolved.yaml') as file_handle:
    resolved = yaml.safe_load(file_handle)
inspect_config(resolved)
runs = []
for event in fixture_events('repository_commit'):
    runs.append(trigger_run(resolved, 'repository_commit', event, {'quality': fatal_dataset}))
assert status(runs[0], 'training') == 'SUCCESS'
assert status(runs[1], 'quality') == 'FAILURE'
assert status(runs[1], 'training') == 'SKIPPED'
event = {'branch': trigger_branch, 'snapshot_id': selected_case}
selected_run = trigger_run(resolved, 'repository_commit', event, {'quality': fatal_dataset})
report = {'config': resolved, 'results': results, 'retained': retained, 'runs': runs, 'selected_run': selected_run, 'false_assert_raises': assertion_failure()}
